{"action":"write_file","path":"slugify.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { slugify } = require('./slugify');

test('lower-cases and joins words with a dash', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('handles accents', () => {
  assert.equal(slugify('Café'), 'cafe');
});

test('handles multiple non-alphanumeric characters', () => {
  assert.equal(slugify('Hello   World!!!'), 'hello-world');
});

test('trims leading and trailing dashes', () => {
  assert.equal(slugify('-Hello World-'), 'hello-world');
});

test('handles text with nothing usable', () => {
  assert.equal(slugify('!@#$'), '');
});

test('throws TypeError when not a string', () => {
  assert.throws(() => slugify(123), TypeError);
  assert.throws(() => slugify(null), TypeError);
  assert.throws(() => slugify(undefined), TypeError);
});
"}
```

